def reshape_parametric_constant(tensor: CooTensor, new_m: int, new_n: int) -> CooTensor:
    """Reshape extracted constant data into matrix format."""
    # The input tensor is in column format ((m*n, 1) per parameter slice);
    # entries are re-mapped to matrix coordinates in F-order. This is exactly
    # coo_reshape for both the parametrized and the parameter-free case.
    return coo_reshape(tensor, new_m, new_n)

