"""Broad check of supported ND/parametric ops vs param-free ground truth."""
from __future__ import annotations

import sys
import warnings
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent / "source"))
sys.path.insert(0, str(Path(__file__).parent))

warnings.filterwarnings("ignore")

import cvxpy as cp
import numpy as np

failures = []


def check(name, make_param_model, vals, solver=cp.SCS, backends=("CPP", "SCIPY", "COO")):
    """make_param_model(param_dict_names)->(problem, params). vals: name->value."""
    # ground truth with constants
    const_model, _ = make_param_model(False)
    try:
        const_val = const_model.solve(solver=solver)
    except Exception as e:
        failures.append(f"{name}: param-free failed: {e}")
        return
    for backend in backends:
        try:
            (prob, params) = make_param_model(True)
            for k, v in vals.items():
                params[k].value = v
            v = prob.solve(solver=solver, canon_backend=backend)
            ok = (v is not None and np.isfinite(v)
                  and np.isclose(v, const_val, rtol=2e-3, atol=1e-6))
            if not ok:
                failures.append(f"{name} [{backend}]: {v} != {const_val}")
        except Exception as e:
            failures.append(f"{name} [{backend}]: exception {type(e).__name__}: {e}")


rng = np.random.default_rng(0)
S, NS, NC = 3, 3, 2  # steps, state dim, control dim

# 1. batched param @ vector slice (the workflow op)
def m1(use_param):
    p = {("A" if use_param else "A"): None}
    if use_param:
        A = cp.Parameter((S, NS, NC), name="A")
    else:
        A = None
    x = [cp.Variable(NC, name=f"x{t}") for t in range(2)]
    terms = []
    for t in range(2):
        lhs = (A[t] if use_param else m1.Avals[t])
        terms.append(lhs @ x[t])
    obj = cp.Minimize(cp.sum_squares(terms[0] + terms[1] - np.arange(NS)))
    return cp.Problem(obj, [cp.norm_inf(x[t]) <= 5 for t in range(2)]), ({"A": A} if use_param else {})


m1.Avals = rng.normal(size=(S, NS, NC))[:2]
check("batched param @ x", m1, {"A": m1.Avals}, backends=("SCIPY", "COO"))

# 2. x @ batched param (rmul with param)
def m2(use_param):
    if use_param:
        M = cp.Parameter((S, NC, NS), name="M")
    else:
        M = None
    x = cp.Variable(NC, name="x")
    res = (M[1] if use_param else m2.Mvals[1])
    obj = cp.Minimize(cp.sum_squares(x @ res - np.ones(NS)))
    return cp.Problem(obj, [cp.norm_inf(x) <= 5]), ({"M": M} if use_param else {})


m2.Mvals = rng.normal(size=(S, NC, NS))
check("x @ param slice", m2, {"M": m2.Mvals}, backends=("SCIPY", "COO"))

# 3. param indexing transpose + broadcast: (A[t].T @ x) and elementwise broadcast
def m3(use_param):
    if use_param:
        A = cp.Parameter((S, NS, NS), name="A")
    else:
        A = None
    x = cp.Variable(NS, name="x")
    M = (A[0].T if use_param else m3.Avals[0].T)
    obj = cp.Minimize(cp.sum_squares(M @ x - np.ones(NS)))
    return cp.Problem(obj, [cp.norm_inf(x) <= 3]), ({"A": A} if use_param else {})


m3.Avals = rng.normal(size=(S, NS, NS))
check("param.T @ x", m3, {"A": m3.Avals}, backends=("SCIPY", "COO"))

# 4. batched const (non-param) @ batched variable: batch-varying constant path
def m4(use_param):
    C = m4.Cvals  # (S, NS, NC) plain ndarray
    X = cp.Variable((S, NC, NS), name="X")
    obj = cp.Minimize(cp.sum_squares(C @ X - 1.0))
    return cp.Problem(obj, [cp.norm(X, "fro") <= 8]), {}


m4.Cvals = rng.normal(size=(S, NS, NC))
check("batch const @ batch var", m4, {}, backends=("SCIPY",))  # ND var >2d forced scipy

# 5. ND variable broadcast/matmul with 2D constant
def m5(use_param):
    C = m5.Cvals2  # (NC, NS) plain ndarray
    X = cp.Variable((S, NC, NS), name="X")
    obj = cp.Minimize(cp.sum_squares(C @ X))
    return cp.Problem(obj, [cp.sum_squares(X) <= 40]), {}


m5.Cvals2 = rng.normal(size=(NC, NS))
check("2D const @ ND var", m5, {}, backends=("SCIPY",))

# 6. ND param sliced then transposed via explicit transpose atom
def m6(use_param):
    if use_param:
        A = cp.Parameter((S, NS, NS), name="A")
    else:
        A = None
    x = cp.Variable(NS, name="x")
    T = (A if use_param else m6.Avals)
    obj = cp.Minimize(cp.sum_squares((A if use_param else T)[0] @ x))
    return cp.Problem(obj, [cp.norm_inf(x) <= 3]), ({"A": A} if use_param else {})


m6.Avals = m3.Avals
check("param slice @ x", m6, {"A": m6.Avals}, backends=("SCIPY", "COO"))

# 7. param mul_elem (param * variable)
def m7(use_param):
    if use_param:
        w = cp.Parameter((NS,), name="w", nonneg=True)
    else:
        w = None
    x = cp.Variable(NS, name="x")
    obj = cp.Minimize(cp.sum_squares(cp.multiply(w if use_param else m7.wvals, x)))
    return cp.Problem(obj, [x >= -1]), ({"w": w} if use_param else {})


m7.wvals = np.abs(rng.normal(size=NS))
check("param * x elementwise", m7, {"w": m7.wvals}, backends=("CPP", "SCIPY", "COO"))

# 8. ND param sum/reshape ops
def m8(use_param):
    if use_param:
        A = cp.Parameter((S, NS), name="A")
    else:
        A = None
    x = cp.Variable(NS, name="x")
    AA = (A if use_param else m8.Avals)
    expr = cp.sum(AA, axis=0) + cp.reshape(AA, (S * NS,), order="F")[:NS]
    obj = cp.Minimize(cp.sum_squares(expr * x - 1.0))
    return cp.Problem(obj, [cp.norm_inf(x) <= 4]), ({"A": A} if use_param else {})


m8.Avals = rng.normal(size=(S, NS))
check("ND param sum/reshape", m8, {"A": m8.Avals}, backends=("SCIPY", "COO"))

print("checked ops; failures:", len(failures))
for f in failures:
    print("  ", f)
sys.exit(1 if failures else 0)

